content.content:
.quote-mark { color: var(--accent); font-family: var(--font-headline); }

/* ============================================================
   Slide 1 — Title
   ============================================================ */
.s-title { flex-direction: column; }
.title-layout {
  display: grid; grid-template-columns: minmax(0, 1.15fr) minmax(340px, 0.85fr);
  align-items: center; gap: clamp(3rem, 7vw, 7rem);
}
.s-title .logo { width: min(250px, 32vw); margin: 0 0 3rem; display: block; }
.title-location {
  display: flex; align-items: center; gap: 0.7rem; margin-bottom: 1.35rem;
  font-family: var(--font-mono); font-size: 0.72rem; font-weight: 700;
  letter-spacing: 0.18em; color: var(--text-dim);
}
.title-location::before { content: ""; width: 2.4rem; height: 1px; background: var(--accent); }
.title-location span { color: var(--accent); font-family: var(--font-kannada); letter-spacing: 0.04em; }
.s-title h1 {
  font-family: var(--font-kannada); font-size: clamp(2.55rem, 4.75vw, 5rem);
  color: var(--text-muted); font-weight: 520; line-height: 1.2; letter-spacing: -0.025em;
}
.s-title h1 strong { color: var(--text); font-weight: 700; }
.title-translation {
  margin-top: 1.5rem; color: var(--text-dim); font-size: clamp(0.95rem, 1.25vw, 1.2rem);
}
.title-translation strong { color: var(--text-muted); font-weight: 600; }
.s-title .title-tagline {
  margin-top: 2.6rem;
  font-family: var(--font-mono); font-size: 0.72rem;
  letter-spacing: 0.18em; text-transform: uppercase; color: var(--text-dim);
}
.s-title .title-tagline em { color: var(--accent); font-style: normal; }
.title-visual {
  position: relative; width: min(430px, 38vw); aspect-ratio: 1; justify-self: center;
  display: grid; place-items: center;
}
=== close ===
  font-family: var(--font-mono); font-size: 2.2rem; transform: rotate(-18deg);
  animation: wave 1.8s ease-in-out infinite;
}
@keyframes wave { 50% { transform: rotate(8deg) translateY(-4px); } }
.close-eyebrow {
  font-family: var(--font-mono); font-size: 0.68rem; font-weight: 700;
  letter-spacing: 0.2em; color: var(--text-dim); margin-bottom: 1rem;
}
.s-close h2 {
  font-family: var(--font-kannada); font-size: clamp(3rem, 6vw, 6.5rem); line-height: 1.1;
  margin: 0; color: var(--text); font-weight: 680; letter-spacing: -0.025em;
}
.s-close h2 strong { color: var(--accent); font-weight: 720; }
.close-kannada {
  font-family: var(--font-kannada); font-size: clamp(1.25rem, 2.1vw, 2rem);
  color: var(--text-muted); margin-top: 1.3rem; line-height: 1.45;
}
.close-kannada strong { color: var(--text); }
.close-translation { margin-top: 0.5rem; color: var(--text-dim); font-size: 0.95rem; }
.close-translation strong { color: var(--text-muted); font-weight: 600; }
.close-links {
  margin-top: 2.7rem; display: flex; align-items: center; justify-content: center; gap: 1.1rem;
  font-family: var(--font-mono); font-size: 0.68rem; letter-spacing: 0.08em; color: var(--text-dim);
}
.close-links .close-logo { width: 112px; opacity: 0.84; display: block; }
.close-links span { width: 3px; height: 3px; border-radius: 50%; background: var(--accent); }
