  1	/* Entire deck — navigation, fragments, hash routing */
  2	(() => {
  3	  const slides = Array.from(document.querySelectorAll(".slide"));
  4	  const progress = document.getElementById("progress");
  5	  const hudCounter = document.getElementById("hudCounter");
  6	  const hudAct = document.getElementById("hudAct");
  7	  const total = slides.length;
  8	  let current = -1;
  9	
 10	  const clamp = (n) => Math.max(0, Math.min(total - 1, n));
 11	
 12	  function fragmentsOf(slide) {
 13	    return Array.from(slide.querySelectorAll("[data-fragment]"));
 14	  }
 15	
 16	  function show(n, { revealAll = false } = {}) {
 17	    n = clamp(n);
 18	    if (n === current) return;
 19	    const prev = slides[current];
 20	    if (prev) {
 21	      prev.classList.remove("active");
 22	      // reset fragments so re-entering replays them
 23	      fragmentsOf(prev).forEach((f) => f.classList.remove("revealed"));
 24	    }
 25	    current = n;
 26	    const slide = slides[n];
 27	    // force animation restart: reflow between class removal and re-add
 28	    void slide.offsetWidth;
 29	    slide.classList.add("active");
 30	    if (revealAll) fragmentsOf(slide).forEach((f) => f.classList.add("revealed"));
 31	
 32	    progress.style.width = `${((n + 1) / total) * 100}%`;
 33	    hudCounter.textContent = `${String(n + 1).padStart(2, "0")} / ${total}`;
 34	    const act = slide.dataset.act || "";
 35	    hudAct.innerHTML = act ? act.replace(/^(Act \d+)/, "<em>$1</em>") : "";
 36	    history.replaceState(null, "", `#${n + 1}`);
 37	  }
 38	
 39	  function next() {
 40	    const pending = fragmentsOf(slides[current]).find((f) => !f.classList.contains("revealed"));
 41	    if (pending) { pending.classList.add("revealed"); return; }
 42	    show(current + 1);
 43	  }
 44	
 45	  function back() {
 46	    const revealed = fragmentsOf(slides[current]).filter((f) => f.classList.contains("revealed"));
 47	    if (revealed.length) { revealed[revealed.length - 1].classList.remove("revealed"); return; }
 48	    // going backwards: land with fragments already revealed
 49	    show(current - 1, { revealAll: true });
 50	  }
 51	
 52	  document.addEventListener("keydown", (e) => {
 53	    if (e.metaKey || e.ctrlKey || e.altKey) return;
 54	    switch (e.key) {
 55	      case "ArrowRight":
 56	      case "ArrowDown":
 57	      case " ":
 58	      case "PageDown":
 59	        e.preventDefault(); next(); break;
 60	      case "ArrowLeft":
 61	      case "ArrowUp":
 62	      case "PageUp":
 63	        e.preventDefault(); back(); break;
 64	      case "Home":
 65	        e.preventDefault(); show(0); break;
 66	      case "End":
 67	        e.preventDefault(); show(total - 1); break;
 68	      case "f":
 69	      case "F":
 70	        toggleFullscreen(); break;
 71	      case "b":
 72	      case "B":
 73	        document.body.classList.toggle("blackout"); break;
 74	      case "Escape":
 75	        document.body.classList.remove("blackout"); break;
 76	    }
 77	  });
 78	
 79	  function toggleFullscreen() {
 80	    if (document.fullscreenElement) document.exitFullscreen();
 81	    else document.documentElement.requestFullscreen().catch(() => {});
 82	  }
 83	
 84	  // click left/right thirds to navigate (ignore clicks on links)
 85	  document.addEventListener("click", (e) => {
 86	    if (e.target.closest("a, button")) return;
 87	    const x = e.clientX / window.innerWidth;
 88	    if (x > 0.72) next();
 89	    else if (x < 0.28) back();
 90	  });
 91	
 92	  // touch swipe
 93	  let touchX = null;
 94	  document.addEventListener("touchstart", (e) => { touchX = e.touches[0].clientX; }, { passive: true });
 95	  document.addEventListener("touchend", (e) => {
 96	    if (touchX === null) return;
 97	    const dx = e.changedTouches[0].clientX - touchX;
 98	    if (Math.abs(dx) > 48) (dx < 0 ? next() : back());
 99	    touchX = null;
100	  }, { passive: true });
101	
102	  // respond to manual hash edits
103	  window.addEventListener("hashchange", () => {
104	    const n = parseInt(location.hash.slice(1), 10);
105	    if (!Number.isNaN(n)) show(n - 1);
106	  });
107	
108	  // start at hash or 0
109	  const start = parseInt(location.hash.slice(1), 10);
110	  show(Number.isNaN(start) ? 0 : start - 1);
111	})();

